676	fused_decoder_megakernel_tc(PersistentContext ctx,
677	                            float* __restrict__ params,
678	                            DecoderTokenCtx tok,
679	                            float* __restrict__ grad,
680	                            float lr, int step, FusedOptState st,
681	                            ::sg::fused::par::CommCtx comm = {}) {
682	#if SG_DEC_TC_DYNAMIC_SMEM
683	    // DEEP-RING path: DecTcSmem is allocated from DYNAMIC smem (sized at launch to
684	    // exactly sizeof(DecTcSmem), opt-in via cudaFuncAttributeMaxDynamicSharedMem-
685	    // orySize) so the deeper fwd/dX ring can exceed the 48 KB STATIC __shared__
686	    // cap. The extern __shared__ base is 16 B-aligned on sm_90 and DecTcSmem's
687	    // alignment is 16 B (static_assert above), so the reinterpret_cast is
688	    // well-defined; the placed object has the IDENTICAL layout/footprint as the
689	    // static path — this is purely WHERE it lives (dynamic vs static smem), not a
690	    // math/layout/access change (parity by construction).
691	    extern __shared__ char sg_dectc_pool[];
692	    DecTcSmem& sm = *reinterpret_cast<DecTcSmem*>(sg_dectc_pool);
693	#else
694	    __shared__ DecTcSmem sm;
695	#endif
696	    GridBarrier bar = ctx.barrier();
697	    // TP transport (folds to nothing on SingleGPU — kTPComm==false). Built once;
698	    // the four reduce points (model_stage_decoder_tc.cuh ①/②/①'/②') read `tr`.
699	    // make_transport_from_comm picks Loopback (no NVSHMEM) or Nvshmem (-DSG_HAS_NVSHMEM).
700	    auto tr = ::sg::fused::sm90::tp::make_transport_from_comm<Par>(comm);
701	    (void)tr;  // unused on SingleGPU (if-constexpr'd out below) — silence the warn
702	    // SAM-coupled cells run the tile fwd+bwd TWICE (P1 + P2.4); route BOTH their
703	    // passes through the out-of-line shims (one shared frame, campaign C2). The
704	    // single-pass cells keep the inline bodies -- byte-identical allocation.
705	    constexpr bool kSamCoupled = (Opt == OptId::LookSAM || Opt == OptId::SuperGrok11 ||
706	                                  Opt == OptId::SuperGrok15 || Opt == OptId::SuperGrok2);
707	    const int cta = blockIdx.x;
708	    const int nCTA = (int)ctx.n_ctas;
709	    const int B = tok.B;
710	    const int T = B * dec::kSeq;
711	
712	    // Workspace partition.
713	    float* ws = tok.workspace;

831	    // ── Build the embedding token lists (counting sort over tok_ids) ONCE on cta 0,
832	    //    HERE in the P1 window so it overlaps the other CTAs' fwd/bwd and the
833	    //    already-present B1 barrier fences it before the P2 consume — NO new barrier.
834	    //    cta 0 then joins P1. The build is O(T), parallel over its worker lanes, so
835	    //    it measures ~0.3 ms (≪ P1) — far below the embed-consume time it unlocks. ──
836	    if (cta == 0)
837	        dectc::dectc_embed_build_lists(tok.tokens, T, embed_row_start, embed_perm);
838	
839	    // ── P1: token-tile-parallel fwd+bwd. Each CTA grid-strides over tiles of
840	    //    kTileM rows; for its tile it runs fwd (→ acts X, NLL) then bwd (→ acts
841	    //    dY, dh0, LN-vec partials). Barrier-free within the tile. ──
842	    const int nrows_tile = dectc::kTileM;
843	    const int n_tiles = (T + nrows_tile - 1) / nrows_tile;
844	    float nll_acc = 0.0f;
845	#ifdef SG_DEC_PROFILE
846	    unsigned long long prof_fwd = 0, prof_bwd = 0;
847	#endif
