849	        const int g0 = ti * nrows_tile;
850	        const int nrows = (T - g0) < nrows_tile ? (T - g0) : nrows_tile;
851	#ifdef SG_DEC_PROFILE
852	        __syncthreads(); unsigned long long _c0 = clock64();
853	#endif
854	        float nll;
855	        if constexpr (kSamCoupled)
856	            nll = dectc::dectc_forward_tile_outlined(w, wb, g0, nrows, acts, sc, tok.tokens,
857	                                                     tok.targets, sm.sA, sm.sB, sm.red SG_DEC_PIPE_BARS_ARG);
858	        else
859	            nll = dectc::dectc_forward_tile(w, wb, g0, nrows, acts, sc, tok.tokens, tok.targets,
860	                                            sm.sA, sm.sB, sm.red SG_DEC_PIPE_BARS_ARG);
861	#ifdef SG_DEC_PROFILE
862	        __syncthreads(); unsigned long long _c1 = clock64();
863	#endif
864	        if constexpr (kSamCoupled)
865	            dectc::dectc_backward_tile_outlined(w, wb, g0, nrows, B, acts, sc, tok.targets,
866	                                                my_lnvec, sc.work2, sm.sA, sm.sB, sm.red SG_DEC_PIPE_BARS_ARG);
867	        else
868	            dectc::dectc_backward_tile(w, wb, g0, nrows, B, acts, sc, tok.targets,
869	                                       my_lnvec, sc.work2, sm.sA, sm.sB, sm.red SG_DEC_PIPE_BARS_ARG);
