872	        if (threadIdx.x == 0) { prof_fwd += _c1 - _c0; prof_bwd += _c2 - _c1; }

1518	// nCTA (the dW/embedding owner maps are functions of nCTA).
1519	template <OptId Opt>
1520	cudaError_t launch_fused_decoder_megakernel_tc(
1521	        PersistentContext ctx, float* params, DecoderTokenCtx tok,
1522	        float* grad, float lr, int step, FusedOptState st, cudaStream_t stream,
1523	        int ncta_cap = 0) {
1524	    int dev = 0;
1525	    cudaError_t err = cudaGetDevice(&dev);
1526	    if (err != cudaSuccess) return err;
1527	    int n_sms = 0;
1528	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
1529	    if (err != cudaSuccess) return err;
1530	
1531	    // Hang-freedom: certify one block/SM occupancy with the ACTUAL dynamic smem.
1532	    // DEFAULT (static DecTcSmem): 0 dynamic bytes — unchanged. DEEP RING
1533	    // (SG_DEC_TC_DYNAMIC_SMEM): DecTcSmem lives in DYNAMIC smem, so certify against
1534	    // its real sizeof — and opt the func in to >48 KB dynamic smem FIRST (the cap
1535	    // the occupancy query and the launch both honor). If the deeper ring can't
1536	    // place one block/SM at its real footprint, REFUSE here (the grid barrier
1537	    // requires ≥1 CTA/SM — proceeding would hang); that is the honest "won't
1538	    // launch" signal, surfaced as cudaErrorLaunchOutOfResources, not silenced.
1539	#if SG_DEC_TC_DYNAMIC_SMEM
1540	    const int dyn_smem = (int)sizeof(DecTcSmem);
1541	    err = cudaFuncSetAttribute(
1542	        (const void*)&fused_decoder_megakernel_tc<Opt>,
1543	        cudaFuncAttributeMaxDynamicSharedMemorySize, dyn_smem);
1544	    if (err != cudaSuccess) return err;
1545	#else
1546	    const int dyn_smem = 0;   // static DecTcSmem — byte-identical to the shipped cert
1547	#endif
1548	    int occ = 0;
1549	    err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
1550	        &occ, (const void*)&fused_decoder_megakernel_tc<Opt>, SG_TC_MEGA_BLOCK,
1551	        /*dynamicSMemBytes=*/dyn_smem);
1552	    if (err != cudaSuccess) return err;
1553	    if (occ < 1) return cudaErrorLaunchOutOfResources;
1554	
1555	    unsigned launch_ctas = (unsigned)n_sms;
1556	    if (ncta_cap > 0 && (unsigned)ncta_cap < launch_ctas) launch_ctas = (unsigned)ncta_cap;
1557	    ctx.n_ctas = launch_ctas;
1558	    // B%16 required (the dW K-loop contracts K=T=B*kSeq and K=B in 16-step atoms,
1559	    // AND it guarantees full token tiles for the projections). NO G-divisibility
1560	    // guard: the split-K dW uses a FLOOR-BALANCED K-partition (dectc_dw_run_tile_
1561	    // splitk) that sums to KS exactly for any KS≥G, so it works at the production
1562	    // truncated B (e.g. 4176, where head KS=B/16=261 is NOT divisible by G=4).
1563	    if ((tok.B % 16) != 0) return cudaErrorInvalidValue;
1564	
1565	    if (ctx.g_arrived) { err = cudaMemsetAsync(ctx.g_arrived, 0, sizeof(unsigned), stream); if (err) return err; }
1566	    if (ctx.g_generation) { err = cudaMemsetAsync(ctx.g_generation, 0, sizeof(unsigned), stream); if (err) return err; }
1567	    if (ctx.g_next_task) { err = cudaMemsetAsync(ctx.g_next_task, 0, sizeof(int), stream); if (err) return err; }
1568	
1569	    dim3 grid(launch_ctas), block(SG_TC_MEGA_BLOCK);
1570	    // dynamicSMemBytes: 0 on the default (static DecTcSmem → byte-identical launch);
1571	    // sizeof(DecTcSmem) on the deep-ring path (dyn_smem, opt-in already set + the
1572	    // ≥1-CTA cert passed above). Same grid/block/stream either way — 1 CTA/SM (the
1573	    // persistent grid-barrier requires it) is preserved.
1574	    fused_decoder_megakernel_tc<Opt><<<grid, block, dyn_smem, stream>>>(
1575	        ctx, params, tok, grad, lr, step, st);
1576	    return cudaGetLastError();
1577	}
1578	
1579	#endif  // SG_TUNED_GEMM_IMPL == SG_GEMM_IMPL_WGMMA

