1525	//    a(work)   := X_ctx @ out_w^T ; r1=X_in+a+out_b (work); n1(r1)→x1(fp32)→X_x1[li]
1526	//    ff0(work) := X_x1 @ ff0_w^T ; (ff0+ff0_b)→ff0pre(bf16); gelu(ff0+ff0_b)→X_gact[li](bf16)
1527	//    ff2(work) := X_gact @ ff2_w^T ; r2=x1+ff2+ff2_b (work); n2(r2)→X_in[li+1]
1528	//                 (last layer: n2→finalin fp32, the head input)
1529	//  BIASES (in/out/ff0/ff2) are folded in fp32 at these points (the oracle adds
1530	//  them in fp32 after the bf16 matmul); LN β + head out_b were already applied.
1531	// ════════════════════════════════════════════════════════════════════════
1532	__device__ float dectc_forward_tile(
1533	        const DecWeights& w, const DecWBf& wb, int g0, int nrows, const DecActs& acts,
1534	        const DecTileScratch& sc, const int* __restrict__ tok_ids,
1535	        const int* __restrict__ tgt_ids,
1536	        __nv_bfloat16* sA, __nv_bfloat16* sB, float* red,
1537	        unsigned long long* pipeBars = nullptr) {
1538	    const int nsamp = nrows / dec::kSeq;
1539	    // ── Embedding: X_in[0][r] = tok[token_id[g0+r]] + pos[(g0+r)%S]. bf16. ──
1540	    for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
1541	        const int r = idx / dec::kD, j = idx % dec::kD;
1542	        const int g = g0 + r;
1543	        const int tid = tok_ids[g];
1544	        const int sp = g % dec::kSeq;            // position within the sample
1545	        float v = w.tok[(int64_t)tid * dec::kD + j] + w.pos[(int64_t)sp * dec::kD + j];
1546	        acts.X_in[0][(int64_t)g * dec::kD + j] = __float2bfloat16(v);
1547	    }
1548	    __syncthreads();
1549	
1550	    for (int li = 0; li < dec::kLayers; ++li) {
1551	        const DecWeights::Layer& L = w.layer[li];
1552	        const __nv_bfloat16* Xin = acts.X_in[li] + (int64_t)g0 * dec::kD;        // [nrows,d]
1553	        // qkv = Xin @ in_w^T + in_b   (N=3d, K=d). bf16 → scratch.qkv[li].
1554	        dectc_gemm_fwd<SG_TUNED_TILE_N>(Xin, wb.in_w[li], sc.qkv[li], dec::kD, 3 * dec::kD, sA, sB, pipeBars);
1555	        __syncthreads();
1556	        // add in_b (the fwd GEMM did W only; bias folded in scalar here for qkv —
1557	        // matches the bf16-faithful oracle qkv = bf(x_in @ bf(in_w)^T + in_b)).
1558	        for (int idx = threadIdx.x; idx < nrows * 3 * dec::kD; idx += blockDim.x) {
1559	            const int j = idx % (3 * dec::kD);
1560	            float v = __bfloat162float(sc.qkv[li][idx]) + L.in_b[j];
1561	            sc.qkv[li][idx] = __float2bfloat16(v);
1562	        }
1563	        __syncthreads();
1564	        // attention → ctx (work fp32) + attn[li] weights.
1565	        dectc_attn_fwd_tile(sc.qkv[li], nrows, sc.work, sc.attn[li]);
1566	        // ctx bf16 → X_ctx[li] (out_proj input + its dW operand).
1567	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
1568	            const int r = idx / dec::kD, j = idx % dec::kD;
1569	            acts.X_ctx[li][(int64_t)(g0 + r) * dec::kD + j] = __float2bfloat16(sc.work[(int64_t)r * dec::kD + j]);
1570	        }
1571	        __syncthreads();
1572	        // a = X_ctx @ out_w^T (+ out_b)  (N=d, K=d). fp32 → work.
1573	        dectc_gemm_fwd_f32<SG_TUNED_TILE_N>(acts.X_ctx[li] + (int64_t)g0 * dec::kD, wb.out_w[li],
1574	                                            sc.work, dec::kD, dec::kD, sA, sB, pipeBars);
1575	        __syncthreads();
1576	        // r1 = Xin + a + out_b → work (fp32). out_b folded here (the GEMM did W only)
1577	        // — matches the oracle a = ctx_b @ out_w^T + out_b kept fp32 through r1.
1578	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
1579	            const int r = idx / dec::kD, j = idx % dec::kD;
1580	            sc.work[(int64_t)r * dec::kD + j] += __bfloat162float(Xin[(int64_t)r * dec::kD + j]) + L.out_b[j];
1581	        }
1582	        __syncthreads();
1583	        // n1(r1) → x1 (fp32) + caches[li]; then bf16 → X_x1[li] (ff0 input + dW operand).
1584	        dectc_ln_fwd_tile(sc.work, L.n1_w, L.n1_b, nrows, sc.x1, sc.n1x[li], sc.n1i[li], red);
1585	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
1586	            const int r = idx / dec::kD, j = idx % dec::kD;
1587	            acts.X_x1[li][(int64_t)(g0 + r) * dec::kD + j] = __float2bfloat16(sc.x1[(int64_t)r * dec::kD + j]);
1588	        }
1589	        __syncthreads();
1590	        // ff0 = X_x1 @ ff0_w^T (+ ff0_b)  (N=dff, K=d). fp32 → work; (pre+b) bf16 →
1591	        // ff0pre; gelu(pre+b) → X_gact[li] (bf16, ff2 input + dW operand). ff0_b folded
1592	        // into pre (fp32) — matches the oracle ff0pre=bf(ff0+b), gact=bf(gelu(ff0+b)).
1593	        dectc_gemm_fwd_f32<SG_TUNED_TILE_N>(acts.X_x1[li] + (int64_t)g0 * dec::kD, wb.ff0_w[li],
1594	                                            sc.work, dec::kD, dec::kDff, sA, sB, pipeBars);
1595	        __syncthreads();
1596	        for (int idx = threadIdx.x; idx < nrows * dec::kDff; idx += blockDim.x) {
1597	            const int r = idx / dec::kDff, j = idx % dec::kDff;
1598	            float pre = sc.work[(int64_t)r * dec::kDff + j] + L.ff0_b[j];
1599	            sc.ff0pre[li][(int64_t)r * dec::kDff + j] = __float2bfloat16(pre);
1600	            acts.X_gact[li][(int64_t)(g0 + r) * dec::kDff + j] = __float2bfloat16(dec_gelu(pre));
1601	        }
1602	        __syncthreads();
1603	        // ff2 = X_gact @ ff2_w^T (+ ff2_b) (N=d, K=dff). fp32 → work.
1604	        dectc_gemm_fwd_f32<SG_TUNED_TILE_N>(acts.X_gact[li] + (int64_t)g0 * dec::kDff, wb.ff2_w[li],
1605	                                            sc.work, dec::kDff, dec::kD, sA, sB, pipeBars);
1606	        __syncthreads();
1607	        // r2 = x1 + ff2 + ff2_b → work (fp32). x1 lives in the dedicated fp32 buffer
1608	        // (no bf16 round). ff2_b folded here — matches the oracle r2 = x1 + (ff2 + ff2_b).
1609	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
1610	            const int r = idx / dec::kD, j = idx % dec::kD;
1611	            sc.work[(int64_t)r * dec::kD + j] += sc.x1[(int64_t)r * dec::kD + j] + L.ff2_b[j];
1612	        }
1613	        __syncthreads();
1614	        if (li + 1 < dec::kLayers) {

1614	        if (li + 1 < dec::kLayers) {
1615	            // n2(r2) → finalin (fp32 reused) + n2 caches[li]; bf16 → X_in[li+1].
1616	            dectc_ln_fwd_tile(sc.work, L.n2_w, L.n2_b, nrows, sc.finalin, sc.n2x[li], sc.n2i[li], red);
1617	            for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
1618	                const int r = idx / dec::kD, j = idx % dec::kD;
1619	                acts.X_in[li + 1][(int64_t)(g0 + r) * dec::kD + j] = __float2bfloat16(sc.finalin[(int64_t)r * dec::kD + j]);
1620	            }
1621	            __syncthreads();
1622	        } else {
1623	            // last layer: n2(r2) → finalin (fp32, all positions; head reads last pos) + n2 caches[li].
1624	            dectc_ln_fwd_tile(sc.work, L.n2_w, L.n2_b, nrows, sc.finalin, sc.n2x[li], sc.n2i[li], red);
1625	        }
1626	    }
1627	
1628	    // ── Final norm + head + CE, scalar PER-SAMPLE on the LAST position only.
1629	    //    finalin holds the last-layer n2 output [nrows,d] fp32. ──
1630	    float nll_acc = 0.0f;
1631	    for (int si = 0; si < nsamp; ++si) {
1632	        const int rlast = si * dec::kSeq + (dec::kSeq - 1);
1633	        const float* hlast = sc.finalin + (int64_t)rlast * dec::kD;
1634	        float sum = 0.0f;
1635	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) sum += hlast[j];
1636	        float mean = dec_block_sum(sum, red) / (float)dec::kD;
1637	        float vs = 0.0f;
1638	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) { float c = hlast[j] - mean; vs += c * c; }
1639	        float var = dec_block_sum(vs, red) / (float)dec::kD;
1640	        float iv = rsqrtf(var + dec::kLnEps);
1641	        if (threadIdx.x == 0) sc.fni[rlast] = iv;
1642	        // fn_xhat cache (last row); hn → X_hn (bf16 head dW operand) AND reuse the
1643	        // X_hn bf16 as the scalar head input (read back below).
1644	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
1645	            float xh = (hlast[j] - mean) * iv;
1646	            sc.fnx[(int64_t)rlast * dec::kD + j] = xh;
1647	            float hn = xh * w.norm_w[j] + w.norm_b[j];
1648	            acts.X_hn[(int64_t)si_global(g0, si) * dec::kD + j] = __float2bfloat16(hn);
1649	        }
1650	        __syncthreads();
1651	        // logits[o] = hn · out_w[o] + out_b[o]  (scalar; hn read from X_hn bf16 so the
1652	        // head input == the head dW operand exactly). Store into sc.logits[si*V..].
1653	        float* lg = sc.logits + (int64_t)si * dec::kVocab;
1654	        const __nv_bfloat16* hnb = acts.X_hn + (int64_t)si_global(g0, si) * dec::kD;
1655	        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) {
1656	            const float* Wr = w.out_w + (int64_t)o * dec::kD;
1657	            float acc = w.out_b[o];
1658	            #pragma unroll 4
1659	            for (int k = 0; k < dec::kD; ++k) acc += __bfloat162float(hnb[k]) * Wr[k];
1660	            lg[o] = acc;
1661	        }
1662	        __syncthreads();
1663	        int tgt = tgt_ids[si_global(g0, si)];
1664	        float lmax = -CUDART_INF_F;
1665	        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) lmax = fmaxf(lmax, lg[o]);
1666	        lmax = dec_block_max(lmax, red);
1667	        float es = 0.0f;
1668	        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) es += __expf(lg[o] - lmax);
1669	        es = dec_block_sum(es, red);
1670	        float logz = lmax + __logf(es);
1671	        if (threadIdx.x == 0) nll_acc += (logz - lg[tgt]);
1672	        __syncthreads();
1673	    }
1674	    return nll_acc;
1675	}
