1677	// Attention BACKWARD over a tile (the oracle's 3-pass form, tile-batched).
1678	// Reads qkv (bf16), attn weights, and dctx [nrows,d] fp32; writes dqkv [nrows,3d]
1679	// fp32 into `dqkv_out`. dsc is the per-CTA dscores scratch. Mirror of
1680	// dec_backward_sample's attention block (A: dv, B: dscores, C: dq/dk), looped
1681	// over the tile's samples. scale = 1/sqrt(dh).
1682	__device__ __forceinline__ void dectc_attn_bwd_tile(
1683	        const __nv_bfloat16* __restrict__ qkv, const float* __restrict__ attn_w,
1684	        const float* __restrict__ dctx, int nrows,
1685	        float* __restrict__ dqkv_out, float* __restrict__ dsc) {
1686	    const int nsamp = nrows / dec::kSeq;
1687	    const float scale = dec::attn_scale();
1688	    // A: dv[kj] = Σ_{qi>=kj} attn[qi,kj] * dctx[qi].  Owner: (sample,kj,head,t).

1757	
1758	// ════════════════════════════════════════════════════════════════════════
1759	//  BACKWARD over one TOKEN TILE. Assumes dectc_forward_tile ran for THIS tile
1760	//  (scratch + DecActs X-inputs populated). Fork B: computes dX via wgmma and
1761	//  WRITES the dY output-adjoints to DecActs (dY_qkv/dY_a/dY_ff0/dY_ff2/
1762	//  dY_logits) + dh0 for P2's output-stationary dW — it does NOT touch the
1763	//  weight dW here. ACCUMULATES the 10 LN-vector grads (γ/β) into the per-CTA
1764	//  LN-vec partials `lnvec` [kNumLnVec × d] (deterministic single-owner-per-j).
1765	//  `B` is the full batch (CE mean scale). Mirrors dec_backward_sample.
1766	//
1767	//  dqkv/dctx/dgact intermediates use the fp32 `work` buffer + a second fp32
1768	//  buffer `work2` (caller passes both, each [nrows×dff]); dh (running adjoint)
1769	//  is the dedicated scratch.dh.
1770	// ════════════════════════════════════════════════════════════════════════
1771	__device__ void dectc_backward_tile(
1772	        const DecWeights& w, const DecWBf& wb, int g0, int nrows, int B, const DecActs& acts,
1773	        const DecTileScratch& sc, const int* __restrict__ tgt_ids,
1774	        float* __restrict__ lnvec, float* __restrict__ work2,
1775	        __nv_bfloat16* sA, __nv_bfloat16* sB, float* red,
1776	        unsigned long long* pipeBars = nullptr) {
1777	    const int nsamp = nrows / dec::kSeq;
1778	    // LN-vec partial slots (dense order; see kLnVecTensorIdx).
1779	    float* gn_n1w[dec::kLayers]; float* gn_n1b[dec::kLayers];
1780	    float* gn_n2w[dec::kLayers]; float* gn_n2b[dec::kLayers];
1781	    for (int li = 0; li < dec::kLayers; ++li) {
1782	        gn_n1w[li] = lnvec + (int64_t)(li * 4 + 0) * dec::kD;
1783	        gn_n1b[li] = lnvec + (int64_t)(li * 4 + 1) * dec::kD;
1784	        gn_n2w[li] = lnvec + (int64_t)(li * 4 + 2) * dec::kD;
1785	        gn_n2b[li] = lnvec + (int64_t)(li * 4 + 3) * dec::kD;
1786	    }
1787	    float* gn_normw = lnvec + (int64_t)(4 * dec::kLayers + 0) * dec::kD;  // 8*kD at L=2
1788	    float* gn_normb = lnvec + (int64_t)(4 * dec::kLayers + 1) * dec::kD;  // 9*kD at L=2
1789	
1790	    // ── CE bwd (per sample): dlogits = (softmax - onehot)/B, overwrite logits.
1791	    //    head bwd: dY_logits[si] = dlogits (the head dW operand); dhn = dlogits@out_w.
1792	    //    final-norm bwd: dh_last (last position only) → scratch.dh (zero others). ──
1793	    // First zero scratch.dh for the whole tile (only last positions get grad).
1794	    for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) sc.dh[idx] = 0.0f;
1795	    __syncthreads();
1796	    for (int si = 0; si < nsamp; ++si) {
1797	        const int rlast = si * dec::kSeq + (dec::kSeq - 1);
1798	        const int gs = si_global(g0, si);
1799	        float* lg = sc.logits + (int64_t)si * dec::kVocab;
1800	        int tgt = tgt_ids[gs];
1801	        // softmax of cached logits.
1802	        float lmax = -CUDART_INF_F;
1803	        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) lmax = fmaxf(lmax, lg[o]);
1804	        lmax = dec_block_max(lmax, red);
1805	        float es = 0.0f;
1806	        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) es += __expf(lg[o] - lmax);
1807	        es = dec_block_sum(es, red);
1808	        float inv_es = 1.0f / es;
1809	        // dlogits → overwrite lg, AND write to dY_logits[gs] (bf16, head dW operand).
1810	        for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) {
1811	            float smo = __expf(lg[o] - lmax) * inv_es;
1812	            float dl = (smo - ((o == tgt) ? 1.0f : 0.0f)) / (float)B;
1813	            lg[o] = dl;
1814	            acts.dY_logits[(int64_t)gs * dec::kVocab + o] = __float2bfloat16(dl);
1815	        }
1816	        __syncthreads();
1817	        // dhn[j] = Σ_o dlogits[o] * out_w[o,j]  (head dX), feature-parallel → dh row rlast.
1818	        // Then final-norm bwd of that single row → scratch.dh[rlast].
1819	        // Use fnx cache (xhat) + fni (inv). Accumulate norm γ/β. (head dW is P2.)
1820	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
1821	            float dhn = 0.0f;
1822	            for (int o = 0; o < dec::kVocab; ++o)
1823	                dhn += lg[o] * w.out_w[(int64_t)o * dec::kD + j];
1824	            // final-norm bwd needs the row-reduce of dxhat; stash dhn into work row rlast.
1825	            sc.work[(int64_t)rlast * dec::kD + j] = dhn;
1826	        }
1827	        __syncthreads();
1828	        // norm γ/β: dnorm_w[j] += dhn*xhat; dnorm_b[j] += dhn. (Only last pos contributes.)
1829	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
1830	            float dhn = sc.work[(int64_t)rlast * dec::kD + j];
1831	            float xh = sc.fnx[(int64_t)rlast * dec::kD + j];
1832	            gn_normw[j] += dhn * xh; gn_normb[j] += dhn;
1833	        }
1834	        __syncthreads();
1835	        // LN dx (single row): dxhat=dhn*norm_w; reduce; dh[rlast] = inv*(dxhat-(sda+xhat*sdax)/d).
1836	        {
1837	            const float* dyr = sc.work + (int64_t)rlast * dec::kD;
1838	            const float* xhr = sc.fnx + (int64_t)rlast * dec::kD;
1839	            float sda = 0.0f, sdax = 0.0f;
1840	            for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
1841	                float dxhat = dyr[j] * w.norm_w[j]; sda += dxhat; sdax += dxhat * xhr[j];
1842	            }
1843	            sda = dec_block_sum(sda, red); sdax = dec_block_sum(sdax, red);
1844	            float iv = sc.fni[rlast];
1845	            for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
1846	                float dxhat = dyr[j] * w.norm_w[j];
1847	                sc.dh[(int64_t)rlast * dec::kD + j] = iv * (dxhat - (sda + xhr[j] * sdax) / (float)dec::kD);
1848	            }
1849	            __syncthreads();
1850	        }
1851	    }
1852	    // scratch.dh now = grad wrt last-layer output [nrows,d] (only last positions nonzero).
1853	
1854	    // ── per-layer backward (reverse). dh is the running adjoint (grad wrt the
1855	    //    layer's n2 output). All fwd intermediates are in scratch/DecActs (NO
1856	    //    recompute). ──
1857	    for (int li = dec::kLayers - 1; li >= 0; --li) {
1858	        const DecWeights::Layer& L = w.layer[li];
1859	        // n2 bwd: dh → dr2 (work fp32), accumulate n2 γ/β. xhat=n2x[li], inv=n2i[li].
1860	        dectc_ln_bwd_tile(sc.dh, sc.n2x[li], sc.n2i[li], L.n2_w, nrows, sc.work, gn_n2w[li], gn_n2b[li], red);
1861	        // r2 = x1 + ff2 → dx1 = dr2 (residual), dff2 = dr2. dff2 → dY_ff2 acts (bf16).
1862	        // dx1 starts as dr2 (copy into work2), the FFN path adds to it.
1863	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
1864	            work2[idx] = sc.work[idx];   // dx1 := dr2 (residual part)
1865	            acts.dY_ff2[li][(int64_t)g0 * dec::kD + idx] = __float2bfloat16(sc.work[idx]);  // dff2
1866	        }
1867	        __syncthreads();
1868	        // ff2 dX: dgact = dff2 @ ff2_w  (N=dff, K=d). fp32 → tw? need a [nrows,dff] buffer.
1869	        //   Use sc.work (currently dr2, no longer needed — dx1 saved in work2, dff2 in acts).
1870	        dectc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_ff2[li] + (int64_t)g0 * dec::kD, wb.ff2_wT[li],
1871	                                           sc.work, dec::kDff, dec::kD, sA, sB, pipeBars);  // dgact [nrows,dff]
1872	        __syncthreads();
1873	        // dff0 = dgact * gelu'(ff0pre) → dY_ff0 acts (bf16) AND keep fp32 in sc.work for dX.
1874	        for (int idx = threadIdx.x; idx < nrows * dec::kDff; idx += blockDim.x) {
1875	            float dff0 = sc.work[idx] * dec_gelu_grad(__bfloat162float(sc.ff0pre[li][idx]));
1876	            sc.work[idx] = dff0;
1877	            acts.dY_ff0[li][(int64_t)g0 * dec::kDff + idx] = __float2bfloat16(dff0);
1878	        }
1879	        __syncthreads();
1880	        // ff0 dX: dx1 += dff0 @ ff0_w  (output width Kin=d, contract Nout=dff). fp32
1881	        //   → sc.x1 (free now — fwd x1 consumed); then add to work2.
1882	        dectc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_ff0[li] + (int64_t)g0 * dec::kDff, wb.ff0_wT[li],
1883	                                           sc.x1, /*Kin=*/dec::kD, /*Nout=*/dec::kDff, sA, sB, pipeBars);  // dx1_ffn [nrows,d]
1884	        __syncthreads();
1885	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x)
1886	            work2[idx] += sc.x1[idx];   // dx1 = residual + FFN path
1887	        __syncthreads();
1888	        // n1 bwd: dx1 (work2) → dr1 (work), accumulate n1 γ/β. xhat=n1x[li], inv=n1i[li].
1889	        dectc_ln_bwd_tile(work2, sc.n1x[li], sc.n1i[li], L.n1_w, nrows, sc.work, gn_n1w[li], gn_n1b[li], red);
1890	        // r1 = x_in + a → da = dr1 (out_proj output adjoint), dx_in = dr1 (residual).
1891	        // SAVE the residual dr1 into sc.dh NOW (dh is free — its grad was consumed into
1892	        // dr2 at the top of this layer); attention bwd will overwrite work2. Then add the
1893	        // in_proj dX path to it. da → dY_a acts (bf16, out_proj dW operand).
1894	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
1895	            sc.dh[idx] = sc.work[idx];   // residual dx_in := dr1  (saved across attn bwd)
1896	            acts.dY_a[li][(int64_t)g0 * dec::kD + idx] = __float2bfloat16(sc.work[idx]);  // da
1897	        }
1898	        __syncthreads();
1899	        // out_proj dX: dctx = da @ out_w  (N=d, K=d). fp32 → sc.work (dctx [nrows,d]).
1900	        dectc_gemm_dx_f32<SG_TUNED_TILE_N>(acts.dY_a[li] + (int64_t)g0 * dec::kD, wb.out_wT[li],
